const input = $input.first().json;

// Prefer structured AI analysis if it already exists
let analysis = input.ai_analysis;

// Otherwise fall back to raw AI output
if (analysis === undefined || analysis === null) {
  analysis = input.ai_analysis_raw;
}

// Final fallback: some AI nodes expose the response as "text"
if (analysis === undefined || analysis === null) {
  analysis = input.text;
}

if (analysis === undefined || analysis === null) {
  throw new Error(
    "No AI analysis found. Expected ai_analysis, ai_analysis_raw, or text."
  );
}

// Already a JSON object — nothing to parse
if (typeof analysis === "object") {
  return [{
    json: {
      ...input,
      ai_analysis: analysis
    }
  }];
}

// Convert string response into JSON
let raw = String(analysis).trim();

// Remove Markdown JSON fences
raw = raw.replace(/^```json\s*/i, "");
raw = raw.replace(/^```\s*/i, "");
raw = raw.replace(/\s*```$/i, "");
raw = raw.trim();

let parsed;

try {
  parsed = JSON.parse(raw);
} catch (error) {
  throw new Error(
    "AI analysis could not be parsed as JSON: " + error.message
  );
}

return [{
  json: {
    ...input,
    ai_analysis: parsed
  }
}];

const results = [];

for (const item of $input.all()) {
  const analysis = item.json.ai_analysis || {};

  const keyPoints = Array.isArray(analysis.key_regulatory_points)
    ? analysis.key_regulatory_points
    : [];

  const obligations = Array.isArray(analysis.obligations)
    ? analysis.obligations
    : [];

  const affectedEntities = Array.isArray(analysis.affected_entities)
    ? analysis.affected_entities
    : [];

  const importantDates = Array.isArray(analysis.important_dates)
    ? analysis.important_dates
    : [];

  const complianceRisks = Array.isArray(analysis.compliance_risks)
    ? analysis.compliance_risks
    : [];

  const requiredActions = Array.isArray(analysis.required_actions)
    ? analysis.required_actions
    : [];

  const interpretationNotes = Array.isArray(analysis.interpretation_notes)
    ? analysis.interpretation_notes
    : [];

  const confidence = Number(analysis.confidence ?? 0);

  // Determine whether there is enough substantive information
  // to make a compliance assessment.
  const hasSubstantiveContent =
    keyPoints.length > 0 ||
    obligations.length > 0 ||
    affectedEntities.length > 0 ||
    complianceRisks.length > 0 ||
    requiredActions.length > 0;

  let analysisStatus;
  let riskLevel;
  let recommendedAction;

  if (!hasSubstantiveContent || confidence === 0) {
    analysisStatus = "INSUFFICIENT_SOURCE_DATA";
    riskLevel = "NOT_ASSESSED";
    recommendedAction =
      "Verify the source document and re-ingest the substantive regulatory text before relying on this analysis.";
  } else if (complianceRisks.length > 0 || requiredActions.length > 0) {
    analysisStatus = "ACTION_REQUIRED";
    riskLevel = "REVIEW_REQUIRED";
    recommendedAction =
      "Review identified regulatory obligations, risks and required actions.";
  } else if (obligations.length > 0) {
    analysisStatus = "COMPLIANCE_REVIEW_REQUIRED";
    riskLevel = "REVIEW_REQUIRED";
    recommendedAction =
      "Review identified obligations and determine applicable compliance controls.";
  } else {
    analysisStatus = "NO_MATERIAL_REQUIREMENTS_IDENTIFIED";
    riskLevel = "LOW";
    recommendedAction =
      "No material compliance requirements were identified by the analysis. Human review remains recommended.";
  }

  results.push({
    json: {
      ...item.json,

      compliance_mapping: {
        analysis_status: analysisStatus,
        risk_level: riskLevel,
        confidence: confidence,

        regulatory_summary:
          analysis.document_summary || "",

        key_regulatory_points: keyPoints,

        obligations: obligations,

        affected_entities: affectedEntities,

        important_dates: importantDates,

        compliance_risks: complianceRisks,

        required_actions: requiredActions,

        interpretation_notes: interpretationNotes,

        recommended_action: recommendedAction
      }
    }
  });
}

return results;

const results = [];

for (const item of $input.all()) {
  const data = item.json;

  // Webhook metadata is stored inside body.
  // Fall back to the root object if the structure changes later.
  const document = data.body || data;

  const mapping = data.compliance_mapping || {};

  results.push({
    json: {
      record_type: "REGULATORY_COMPLIANCE_ANALYSIS",

      document: {
        intake_id: document.intake_id || null,
        document_name: document.document_name || null,
        document_type: document.document_type || null,
        source: document.source || null,
        source_url: document.source_url || null,
        jurisdiction: document.jurisdiction || null,
        received_at: document.received_at || null
      },

      analysis: {
        status: mapping.analysis_status || "UNKNOWN",
        risk_level: mapping.risk_level || "NOT_ASSESSED",
        confidence: mapping.confidence ?? 0,
        summary: mapping.regulatory_summary || ""
      },

      regulatory_intelligence: {
        key_regulatory_points:
          mapping.key_regulatory_points || [],

        obligations:
          mapping.obligations || [],

        affected_entities:
          mapping.affected_entities || [],

        important_dates:
          mapping.important_dates || [],

        compliance_risks:
          mapping.compliance_risks || [],

        required_actions:
          mapping.required_actions || [],

        interpretation_notes:
          mapping.interpretation_notes || []
      },

      decision: {
        recommended_action:
          mapping.recommended_action || null
      },

      processing: {
        processed_at: new Date().toISOString(),
        pipeline_status: "COMPLETED"
      }
    }
  });
}

return results;

const results = [];

// Find a field anywhere inside the incoming JSON object.
function findField(obj, targetKey) {
  if (!obj || typeof obj !== 'object') {
    return undefined;
  }

  if (Object.prototype.hasOwnProperty.call(obj, targetKey)) {
    return obj[targetKey];
  }

  for (const key of Object.keys(obj)) {
    const value = obj[key];

    if (value && typeof value === 'object') {
      const found = findField(value, targetKey);

      if (found !== undefined) {
        return found;
      }
    }
  }

  return undefined;
}

function cleanLabel(value) {
  if (value === null || value === undefined || value === '') {
    return 'Not available';
  }

  return String(value)
    .replace(/_/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toUpperCase();
}

function formatList(value) {
  if (!Array.isArray(value) || value.length === 0) {
    return 'None identified.';
  }

  return value.map(item => {

    if (typeof item === 'object' && item !== null) {

      if (item.date && item.description) {
        return `• ${item.date} — ${item.description}`;
      }

      if (item.date) {
        return `• ${item.date}`;
      }

      return `• ${JSON.stringify(item)}`;
    }

    return `• ${String(item)
      .replace(/_/g, ' ')
      .trim()}`;

  }).join('\n');
}

function formatConfidence(value) {
  if (value === null || value === undefined || value === '') {
    return 'Not available';
  }

  const number = Number(value);

  if (Number.isNaN(number)) {
    return String(value);
  }

  // Our schema uses 0–1.
  // 0.4 becomes 40%.
  if (number >= 0 && number <= 1) {
    return `${Math.round(number * 100)}%`;
  }

  return `${Math.round(number)}%`;
}

for (const item of $input.all()) {

  const data = item.json;

  // Locate fields regardless of their nesting level.
  const document = findField(data, 'document') || {};

  const status = findField(data, 'status');
  const riskLevel = findField(data, 'risk_level');
  const confidence = findField(data, 'confidence');

  const summary = findField(data, 'summary');

  const obligations =
    findField(data, 'obligations') || [];

  const affectedEntities =
    findField(data, 'affected_entities') || [];

  const importantDates =
    findField(data, 'important_dates') || [];

  const complianceRisks =
    findField(data, 'compliance_risks') || [];

  const requiredActions =
    findField(data, 'required_actions') || [];

  const decision =
    findField(data, 'decision') || {};

  const recommendedAction =
    decision.recommended_action ||
    findField(data, 'recommended_action') ||
    'No recommended action provided.';

  const processing =
    findField(data, 'processing') || {};

  const sourceUrl =
    document.source_url ||
    findField(data, 'source_url') ||
    'No source URL available.';

  const pipelineStatus =
    processing.pipeline_status ||
    findField(data, 'pipeline_status') ||
    'UNKNOWN';

  const alertText = `🚨 REGULATORY INTELLIGENCE ALERT

📄 Document
${document.document_name || findField(data, 'document_name') || 'Not available'}

🏛️ Source
${document.source || findField(data, 'source') || 'Not available'}

🌍 Jurisdiction
${document.jurisdiction || findField(data, 'jurisdiction') || 'Not available'}

📑 Type
${document.document_type || findField(data, 'document_type') || 'Not available'}

⚠️ Compliance Status
${cleanLabel(status)}

🔴 Risk Level
${cleanLabel(riskLevel)}

🎯 Confidence
${formatConfidence(confidence)}

📝 Summary
${summary || 'No summary available.'}

📌 Obligations
${formatList(obligations)}

🏢 Affected Entities
${formatList(affectedEntities)}

📅 Important Dates
${formatList(importantDates)}

⚠️ Compliance Risks
${formatList(complianceRisks)}

✅ Required Actions
${formatList(requiredActions)}

💡 Recommended Action
${recommendedAction}

🔗 Source
${sourceUrl}

⚙️ Pipeline Status
${cleanLabel(pipelineStatus)}`;

  results.push({
    json: {
      ...data,
      alert_text: alertText
    }
  });
}

return results;
